INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
VALUES
  ('72c0e868-568b-491d-bb55-a99b9d25a2ec'::uuid, 'a0000000-0000-4000-8000-000000000308'::uuid, 'OH', 'commercial', '99341', 'prior_auth_required', '{"answer":"No PCP referral is needed for a member to be seen by a participating provider, so an in-network home-based palliative visit needs no referral. But if the rendering clinician or practice is NOT participating with Humana Healthy Horizons, prior authorization must be obtained before the service or the claim denies. Stated by service, so it governs every service this practice bills: home / domiciliary E/M visits (99341, 99342, 99344, 99345, 99347, 99348, 99349, 99350), advance care planning (99497, 99498), prolonged services (99417, G0318), transitional care management (99495, 99496), chronic and principal care management (99490, 99439, 99491, 99424-99427) and home health certification / recertification / supervision (G0179, G0180, G0181).","appliesToService":"Requirements regarding the submission and processing of requests for specialist referrals - members seeing participating network providers versus nonparticipating providers","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'varies', 0.80, DATE '2026-01-01', NULL, 'f85ab415-9c8e-4dab-a085-35ba7a0a620d'::uuid, 'Humana Healthy Horizons does not require referrals from PCPs to see participating specialists; however, prior authorization must be obtained for nonparticipating providers.', 'extract:denial-rules-2026-08'),
