  ('c42251b3-436f-49c0-90f0-f75a79578184'::uuid, 'a0000000-0000-4000-8000-000000000201'::uuid, 'SC', 'medicaid_mco', '99426', 'modifier_required', '{"answer":"Any service delivered by telemedicine must carry modifier GT on the CMS-1500. This applies to every in-scope service delivered remotely — E/M in the home 99341-99350, advance care planning 99497/99498, prolonged service 99417 and G0318, transitional care 99495/99496, and chronic/principal care management 99490, 99439, 99491, 99424-99427. Omitting GT on a telemedicine encounter will trigger a missing-modifier edit and denial.","appliesToService":"Telemedicine","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'covered', 0.80, DATE '2026-01-01', NULL, '77290c16-75fd-42b6-8200-f5fa87d64525'::uuid, 'Providers must include modifier GT on the CMS-1500 claim form.', 'extract:denial-rules-2026-08'),
  ('443bbb2a-3990-498b-9dbf-cf4b5b6aca0b'::uuid, 'a0000000-0000-4000-8000-000000000201'::uuid, 'SC', 'medicaid_mco', '99427', 'modifier_required', '{"answer":"Any service delivered by telemedicine must carry modifier GT on the CMS-1500. This applies to every in-scope service delivered remotely — E/M in the home 99341-99350, advance care planning 99497/99498, prolonged service 99417 and G0318, transitional care 99495/99496, and chronic/principal care management 99490, 99439, 99491, 99424-99427. Omitting GT on a telemedicine encounter will trigger a missing-modifier edit and denial.","appliesToService":"Telemedicine","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'covered', 0.80, DATE '2026-01-01', NULL, '77290c16-75fd-42b6-8200-f5fa87d64525'::uuid, 'Providers must include modifier GT on the CMS-1500 claim form.', 'extract:denial-rules-2026-08'),
  ('7525279f-b8ab-43ff-9a75-181f0db7815a'::uuid, 'a0000000-0000-4000-8000-000000000201'::uuid, 'SC', 'medicaid_mco', '99341', 'telehealth_allowed', '{"answer":"A billable telemedicine encounter requires two-way, real-time interactive AUDIO AND VIDEO between the patient and the practitioner at the distant site, on HIPAA-compliant technology. Audio-only contact does not qualify. Do not bill 99341-99350, 99497/99498, 99495/99496 or 99490/99491/99424-99427 as telemedicine unless the video component actually occurred and is documented.","appliesToService":"Telemedicine — requirements for providers to bill for telemedicine","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'varies', 0.80, DATE '2026-01-01', NULL, '77290c16-75fd-42b6-8200-f5fa87d64525'::uuid, 'South Carolina Medicaid reimburses for telemedicine services using interactive telecommunications equipment that includes, at a minimum, audio and video equipment permitting two-way, real time, interactive communication between a patient and a practitioner.', 'extract:denial-rules-2026-08'),
  ('67e8bc1e-70ae-4956-aa18-f2241289310a'::uuid, 'a0000000-0000-4000-8000-000000000201'::uuid, 'SC', 'medicaid_mco', '99342', 'telehealth_allowed', '{"answer":"A billable telemedicine encounter requires two-way, real-time interactive AUDIO AND VIDEO between the patient and the practitioner at the distant site, on HIPAA-compliant technology. Audio-only contact does not qualify. Do not bill 99341-99350, 99497/99498, 99495/99496 or 99490/99491/99424-99427 as telemedicine unless the video component actually occurred and is documented.","appliesToService":"Telemedicine — requirements for providers to bill for telemedicine","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'varies', 0.80, DATE '2026-01-01', NULL, '77290c16-75fd-42b6-8200-f5fa87d64525'::uuid, 'South Carolina Medicaid reimburses for telemedicine services using interactive telecommunications equipment that includes, at a minimum, audio and video equipment permitting two-way, real time, interactive communication between a patient and a practitioner.', 'extract:denial-rules-2026-08'),
