  ('33e76e69-105d-48bc-854f-653e84e188ec'::uuid, 'a0000000-0000-4000-8000-000000000102'::uuid, 'NC', 'medicaid_mco', '99341', 'provider_taxonomy_allowed', '{"answer":"The rendering clinician and the organization must be enrolled and credentialed as an NC Medicaid provider through NCDHHS (NCTracks) before contracting with the plan and before providing any service to a member — no service is payable otherwise. Re-credentialing/re-verification runs every 5 years through NCTracks. If NCDHHS notifies the plan that required documentation was not submitted, the plan stops paying claims within 1 business day, and the provider is removed from the network if the information is not supplied within 50 days.","appliesToService":"Medicaid-enrolled care provider","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'unknown', 0.80, DATE '2026-01-01', NULL, '368783d1-c669-4007-9476-92a53ea6ae06'::uuid, 'You must be enrolled with the department as a North Carolina Medicaid care provider, consistent with applicable care provider disclosure, screening and enrollment requirements.', 'extract:denial-rules-2026-08'),
  ('89ded283-ff81-4f09-b462-18c837315ce5'::uuid, 'a0000000-0000-4000-8000-000000000102'::uuid, 'NC', 'medicaid_mco', '99342', 'provider_taxonomy_allowed', '{"answer":"The rendering clinician and the organization must be enrolled and credentialed as an NC Medicaid provider through NCDHHS (NCTracks) before contracting with the plan and before providing any service to a member — no service is payable otherwise. Re-credentialing/re-verification runs every 5 years through NCTracks. If NCDHHS notifies the plan that required documentation was not submitted, the plan stops paying claims within 1 business day, and the provider is removed from the network if the information is not supplied within 50 days.","appliesToService":"Medicaid-enrolled care provider","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'unknown', 0.80, DATE '2026-01-01', NULL, '368783d1-c669-4007-9476-92a53ea6ae06'::uuid, 'You must be enrolled with the department as a North Carolina Medicaid care provider, consistent with applicable care provider disclosure, screening and enrollment requirements.', 'extract:denial-rules-2026-08'),
