  ('2cdefdcd-93bf-40f4-befb-c32e8bf2866a'::uuid, 'a0000000-0000-4000-8000-000000000105'::uuid, 'NC', 'tribal_638', 'G0179', 'telehealth_allowed', '{"answer":"Yes — the face-to-face encounter that supports a home health certification/recertification may be conducted via telehealth. NC Medicaid expressly includes telehealth in the face-to-face contact requirement (implemented per 42 CFR 440.70 and clinical coverage policy 1H, Telehealth, Virtual Patient Communications and Remote Monitoring). Document the telehealth modality on the attestation; do not deny or delay a G0180/G0179 certification solely because the encounter was virtual.","appliesToService":"Face to Face Encounter — \"face-to-face contact (including the use of telehealth)\" with the beneficiary","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'covered', 0.80, DATE '2026-01-01', NULL, '51ef83c5-5eeb-48d6-bcde-75e266b90541'::uuid, 'contact (including the use of telehealth), was made with the beneficiary within the last 90 days in accordance with Section 6407 of the Patient Protection and Affordable Care Act.', 'extract:denial-rules-2026-08'),
  ('7ce95fae-c398-4484-948d-45103c38ac9c'::uuid, 'a0000000-0000-4000-8000-000000000101'::uuid, 'NC', 'medicaid_mco', 'G0179', 'bundled_with', '{"answer":"Once the beneficiary elects the Medicare or Medicaid hospice benefit, all care related to the terminal illness belongs to hospice and is not payable as home health. Home health may only cover services UNRELATED to the terminal illness. Do not certify, recertify or oversee (G0180/G0179/G0181) a home health plan of care for the terminal condition of a hospice-elected patient; the certified services must be documented as unrelated to the terminal illness.","appliesToService":"Specific Criteria Not Covered / Coordination with Hospice — \"Any services related to terminal illness when the beneficiary has elected Medicare or Medicaid hospice benefits\"","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'varies', 0.80, DATE '2026-01-01', NULL, '71cb275d-8300-4eed-8ae3-76981f38cdba'::uuid, 'Any services related to terminal illness when the beneficiary has elected Medicare or Medicaid hospice benefits (home health services may be provided when they are unrelated to the terminal illness).', 'extract:denial-rules-2026-08'),
  ('872f5221-4858-4ed5-93bd-0a4819f44ec7'::uuid, 'a0000000-0000-4000-8000-000000000101'::uuid, 'NC', 'medicaid_mco', 'G0180', 'bundled_with', '{"answer":"Once the beneficiary elects the Medicare or Medicaid hospice benefit, all care related to the terminal illness belongs to hospice and is not payable as home health. Home health may only cover services UNRELATED to the terminal illness. Do not certify, recertify or oversee (G0180/G0179/G0181) a home health plan of care for the terminal condition of a hospice-elected patient; the certified services must be documented as unrelated to the terminal illness.","appliesToService":"Specific Criteria Not Covered / Coordination with Hospice — \"Any services related to terminal illness when the beneficiary has elected Medicare or Medicaid hospice benefits\"","mappedFrom":"service-level rule mapped to this code"}'::jsonb, 'varies', 0.80, DATE '2026-01-01', NULL, '71cb275d-8300-4eed-8ae3-76981f38cdba'::uuid, 'Any services related to terminal illness when the beneficiary has elected Medicare or Medicaid hospice benefits (home health services may be provided when they are unrelated to the terminal illness).', 'extract:denial-rules-2026-08'),
